  "ct.step1": { en: "You send the brief", es: "Envías el brief", zh: "你发送需求简报", yue: "你發送需求簡報", ru: "Вы отправляете бриф", yi: "איר שיקט דעם בריף", bn: "আপনি ব্রিফ পাঠান", ko: "브리프를 보냅니다", ht: "Ou voye rezime a", it: "Ci invii il brief", ar: "ترسل الملخّص", pl: "Wysyłasz brief" },
