  "ct.step3": { en: "Free 30-min strategy call", es: "Llamada de estrategia gratuita de 30 min", zh: "免费 30 分钟策略通话", yue: "免費 30 分鐘策略通話", ru: "Бесплатный 30-минутный стратегический звонок", yi: "פֿרייַער 30-מינוט סטראַטעגיע רוף", bn: "বিনামূল্যে ৩০ মিনিটের কৌশল কল", ko: "무료 30분 전략 통화", ht: "Apèl estrateji gratis 30 minit", it: "Chiamata strategica gratuita di 30 min", ar: "مكالمة استراتيجية مجانية 30 دقيقة", pl: "Bezpłatna 30-min rozmowa strategiczna" },
  "ct.step4": { en: "Proposal within 24 hours", es: "Propuesta en 24 horas", zh: "24 小时内提交方案", yue: "24 小時內提交方案", ru: "Предложение в течение 24 часов", yi: "פֿאָרשלאָג אין 24 שעה", bn: "২৪ ঘণ্টার মধ্যে প্রস্তাব", ko: "24시간 내 제안서", ht: "Pwopozisyon nan 24 èdtan", it: "Proposta entro 24 ore", ar: "عرض خلال 24 ساعة", pl: "Oferta w ciągu 24 godzin" },
  "ct.sent.h": { en: "Brief received.", es: "Brief recibido.", zh: "已收到需求简报。", yue: "已收到需求簡報。", ru: "Бриф получен.", yi: "בריף באַקומען.", bn: "ব্রিফ পেয়েছি।", ko: "브리프를 받았습니다.", ht: "Nou resevwa rezime a.", it: "Brief ricevuto.", ar: "تمّ استلام الملخّص.", pl: "Brief odebrany." },
  "ct.sent.p": { en: "We'll be in touch within 24 hours. Keep an eye on your inbox.", es: "Nos pondremos en contacto en 24 horas. Revisa tu bandeja de entrada.", zh: "我们会在 24 小时内联系你。请留意你的邮箱。", yue: "我哋會喺 24 小時內聯絡你。請留意你嘅郵箱。", ru: "Мы свяжемся в течение 24 часов. Следите за почтой.", yi: "מיר וועלן זיך פֿאַרבינדן אין 24 שעה. האַלט אַן אויג אויף אײַער אינבאָקס.", bn: "আমরা ২৪ ঘণ্টার মধ্যে যোগাযোগ করব। আপনার ইনবক্সে চোখ রাখুন।", ko: "24시간 내에 연락드리겠습니다. 받은 편지함을 확인해 주세요.", ht: "Nou pral kontakte ou nan 24 èdtan. Veye bwat resepsyon ou.", it: "Ti contatteremo entro 24 ore. Tieni d'occhio la casella di posta.", ar: "سنتواصل معك خلال 24 ساعة. تابع بريدك الوارد.", pl: "Odezwiemy się w ciągu 24 godzin. Miej oko na skrzynkę." },
