  "pv.tpl.legal": { en: "Law Firm", es: "Bufete de Abogados", zh: "律师事务所", yue: "律師事務所", ru: "Юридическая фирма", yi: "אַדוואָקאַט פֿירמע", bn: "আইন সংস্থা", ko: "로펌", ht: "Kabinè Avoka", it: "Studio Legale", ar: "مكتب محاماة", pl: "Kancelaria prawna" },
