  "in.readyWorks": { en: "Ready for a site that works?", es: "¿Listo para un sitio que funciona?", zh: "准备好拥有一个真正有效的网站了吗？", yue: "準備好擁有一個真正有效嘅網站未？", ru: "Готовы к сайту, который работает?", yi: "גרייט פֿאַר אַ וועבזייטל וואָס אַרבעט?", bn: "কার্যকর একটি সাইটের জন্য প্রস্তুত?", ko: "제대로 작동하는 사이트, 준비되셨나요?", ht: "Pare pou yon sit ki mache?", it: "Pronto per un sito che funziona?", ar: "مستعد لموقع يعمل فعلًا؟", pl: "Gotowy na stronę, która działa?" },
  "in.ctaSub": { en: "Flat fee, live in about two weeks, built specifically for your industry.", es: "Tarifa fija, en vivo en unas dos semanas, creado específicamente para tu sector.", zh: "固定收费，约两周内上线，专为你的行业量身打造。", yue: "固定收費，約兩星期內上線，專為你嘅行業度身打造。", ru: "Фиксированная цена, запуск примерно за две недели, создано специально для вашей отрасли.", yi: "פֿלאַכער אָפּצאָל, לעבעדיק אין אַרום צוויי וואָכן, געבויט ספּעציעל פֿאַר אײַער אינדוסטריע.", bn: "নির্দিষ্ট ফি, প্রায় দুই সপ্তাহে লাইভ, আপনার শিল্পের জন্য বিশেষভাবে তৈরি।", ko: "정액 요금, 약 2주 내 오픈, 당신의 업종에 맞춰 제작.", ht: "Frè fiks, anliy nan anviwon de semèn, bati espesyalman pou endistri ou.", it: "Tariffa fissa, online in circa due settimane, realizzato apposta per il tuo settore.", ar: "رسوم ثابتة، إطلاق خلال أسبوعين تقريبًا، مبني خصّيصًا لقطاعك.", pl: "Stała opłata, online w około dwa tygodnie, stworzone specjalnie dla twojej branży." },
  "in.startProject": { en: "Start your project", es: "Inicia tu proyecto", zh: "启动你的项目", yue: "開始你嘅項目", ru: "Начать ваш проект", yi: "אָנהייבן אײַער פּראָיעקט", bn: "আপনার প্রকল্প শুরু করুন", ko: "프로젝트 시작하기", ht: "Kòmanse pwojè ou", it: "Avvia il tuo progetto", ar: "ابدأ مشروعك", pl: "Rozpocznij swój projekt" },
